contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint v) public payable {
        require(true);

        bool setMinReverted;
        c.SetMinSum(v); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            setMinReverted = true;
        } else {
            setMinReverted = false;
        }

        bool initReverted;
        c.Initialized(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            initReverted = true;
        } else {
            initReverted = false;
        }

        uint minSum = c.MinSum(); if (__ESBMC_reverted()) return;

        assert(!setMinReverted && !initReverted && minSum == v);
    }

    receive() external payable {}
}

